"boudin":{word:"SPLOOSH!",color:"#e8c98a",shake:0.55,after:"Sourdough shrapnel. The bread bear never stood a chance.",run(f,d,api){api.sfx("crack");api.anim(f,[{transform:"scale(1)",opacity:1},{transform:"scale(1.1) rotate(3deg)",offset:.2},{transform:"scale(.9) rotate(-7deg)",opacity:.6,offset:.6},{transform:"scale(.28)",opacity:0}],{duration:460,fill:"forwards",easing:"ease-in"});api.burst({emojis:["🍞", "🐻"],count:8,spread:170,rise:110,size:24});api.burst({colors:["#e8c98a", "#d8b46a", "#fff"],count:12,spread:150,rise:85,size:13});setTimeout(function(){api.remains(signSVG("CRUMBS","#e8c98a"));},340);}},
